<dialog class="bj-contact" id="bj-contact" aria-labelledby="bj-contact-title"><button type="button" data-contact-close aria-label="<?php echo esc_attr(bj_t('close')); ?>">×</button><h2 id="bj-contact-title"><?php echo esc_html(bj_t('contact_title')); ?></h2>
<form id="bj-contact-form"><input type="hidden" name="action" value="bj_contact"><label><?php echo esc_html(bj_t('name')); ?><input name="name" autocomplete="name" maxlength="150" required></label><label><?php echo esc_html(bj_t('email')); ?><input type="email" name="email" autocomplete="email" required></label><label><?php echo esc_html(bj_t('phone')); ?><input type="tel" name="phone" autocomplete="tel"></label><label><?php echo esc_html(bj_t('message')); ?><textarea name="message" rows="5" maxlength="10000" required></textarea></label><label class="bj-honey" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="bj-consent"><input type="checkbox" name="consent" value="1" required><?php echo esc_html(bj_t('consent')); ?></label><button class="mt-btn" type="submit"><?php echo esc_html(bj_t('send')); ?></button><p role="status" id="bj-contact-status"></p></form></dialog>
